# Graph Builder Role

You receive a list of source files from a single module (directory) and their
contents. Respond with exactly two tagged lines — no prose, no preamble, nothing else.

## Output format

```
GRAPH_SUMMARY:<one paragraph — what this module does and why it exists>
GRAPH_SUBSYSTEM:<single word grouping — e.g. auth, billing, api, storage, graph, wiki, cli>
```

Rules:
- GRAPH_SUMMARY: one paragraph, no bullets, plain prose
- GRAPH_SUBSYSTEM: one word only
- Output exactly these two lines. Nothing else.


Module path: frontends/platform-chrome/src/config
Files:

--- frontends/platform-chrome/src/config/navigation.ts (761 lines) ---
/**
 * navigation.ts — the platform-chrome navigation registry.
 *
 * PURE DATA. No Paraglide import — `labelKey` is plain string data (a key
 * into `navigationLabels.ts`'s `NAV_LABELS`), so this module can be imported
 * by a Node script or a test with zero Paraglide/React runtime cost. The
 * only non-data import is the shared lucide icon barrel, for `NavApp.icon`
 * (a component reference, asserted unique by identity — see
 * `navigation.test.ts` — never by its stamped CSS class).
 *
 * ── Two role axes, never one ──────────────────────────────────────────────
 *
 * Legacy's single `NavRole` does not transfer to this platform:
 *
 *   - `NavPlane` mirrors shell-bff's OWN partitioning of the MFE registry
 *     (`services/shell-bff/internal/handlers/mfes.go:159-165`, `:190-291`),
 *     lifted to the client. It is NOT a role: a realm admin/org-admin's
 *     registry contains ONLY admin-mfe (confined, early return), while an
 *     org-root OWNER/ADMIN with no realm role gets admin-mfe PREPENDED to
 *     the eleven workspace MFEs — their plane is still "workspace". Only a
 *     realm admin/org-admin's plane is "admin".
 *   - `NavOrgRole` carries `"none"` as a reachable, named first-class state
 *     (a platform admin has no org-membership row) rather than a falsy `""`
 *     — `if (!orgRole)` is exactly how a fail-open bug gets written. Ranked
 *     via `ORG_ROLE_RANK` so `minOrgRole` gating is a comparison, not a set
 *     test.
 *   - `capabilities` (on the wire at `session.go:101`) is deliberately NOT
 *     carried: it's already discarded by the frontend session types, and
 *     realm role "admin" force-grants all seven while `org_role` stays `""`
 *     (`session.go:196-201`) — a strictly weaker discriminator than
 *     plane + orgRole.
 *
 * ── Visibility vs. liveness — two functions over two input objects ───────
 *
 * `isAppVisible(app, ctx: NavContext)` answers "does this row exist in the
 * menu at all" (role/plane/flag gating — an invisible row renders nothing,
 * not a dead placeholder). `resolveLiveness(app, live: NavLiveness)`
 * answers "is this row's destination reachable right now", independent of
 * visibility, in three states — `"pending"` is what fixes the DEAD-flash
 * without adding a fourth render path. Resolution order (first match wins):
 *
 *   1. `href === null`        → dead     (the six placeholders)
 *   2. `mfe === undefined`    → live     (Home/Settings must never flicker)
 *   3. `status === "loading"` → pending
 *   4. `hasWorkspace === false` → dead
 *   5. `mfes.has(mfe)`        → live, else dead
 */

import {
  Activity,
  CalendarClock,
  Files,
  GitFork,
  Home,
  Layers,
  MessageCircleMore,
  MessageSquareQuote,
  MessagesSquare,
  PencilSparkles,
  Settings,
  Shield,
  Target,
  LayoutList,
  type LucideIcon,
} from "@omnicore-platform/ui/icons";
import type { NavLabelKey } from "./navigationLabels";

// ── Role axes ────────────────────────────────────────────────────────────

/**
 * shell-bff's own MFE-registry partitioning, lifted to the client. NOT a
 * role — see the module doc above.
 */
export type NavPlane = "workspace" | "admin";

/**
 * The caller's ORG-ROOT membership role. `"none"` is a reachable first-class
 * state, not a falsy sentinel — see the module doc above.
 */
export type NavOrgRole = "none" | "VIEWER" | "MEMBER" | "ADMIN" | "OWNER";

/**
 * Rank table for `NavOrgRole`, so `minOrgRole` gating is a numeric
 * comparison (`ORG_ROLE_RANK[ctx.orgRole] >= ORG_ROLE_RANK[app.minOrgRole]`)
 * rather than a set-membership test that has to be kept in sync by hand.
 */
export const ORG_ROLE_RANK: Readonly<Record<NavOrgRole, number>> = {
  none: 0,
  VIEWER: 1,
  MEMBER: 2,
  ADMIN: 3,
  OWNER: 4,
};

// ── Feature flags and MFE names — closed, mirrored unions ─────────────────

/**
 * Platform-global vertical flag keys. Mirrors
 * `services/org-svc/internal/domain/feature_flag.go`'s `KnownVerticalKeys`
 * exactly (order included) — `navigation.mirror.test.ts` parses that file
 * and asserts set equality. This is the first place in the repo where a
 * known-key typo is a BUILD failure: today `RequireVerticalEnabled("filez")`
 * is caught by nothing (the cache fails open, so the gate becomes a
 * permanent silent no-op).
 */
export const PLATFORM_FEATURE_FLAGS = [
  "dialogue",
  "range",
  "spaces",
  "studio",
  "ask",
  "workflows",
  "clio",
  "files",
  "monitor",
  "queue",
  "rooms",
] as const;

export type PlatformFeatureFlag = (typeof PLATFORM_FEATURE_FLAGS)[number];

/**
 * Registered Module Federation remote names. Mirrors
 * `services/shell-bff/internal/handlers/mfes.go`'s registry entries — the
 * eleven workspace MFEs plus "admin" — exactly.
 * `navigation.mirror.test.ts` parses that file and asserts set equality.
 *
 * NOTE the three spellings: MFE name "workflow" (singular), flag key
 * "workflows" (plural), route "/workflows". shell-bff carries a separate
 * `flagKey` column solely for this (`mfes.go:259-264`); `NavApp` mirrors
 * that split with separate `mfe` and `flag` fields rather than deriving one
 * from the other — deriving one from the other IS the trap, and it is the
 * live `/workflow` 404 in the command palette today.
 */
export const MFE_NAMES = [
  "admin",
  "files",
  "dialogue",
  "range",
  "clio",
  "workflow",
  "studio",
  "spaces",
  "ask",
  "queue",
  "monitor",
  "rooms",
] as const;

export type MfeName = (typeof MFE_NAMES)[number];

// ── Visibility ──────────────────────────────────────────────────────────

/** Input to `isAppVisible` — everything needed to decide row EXISTENCE. */
export interface NavContext {
  readonly plane: NavPlane;
  readonly orgRole: NavOrgRole;
  /** Currently-enabled platform feature flags. In production this is
   *  effectively "all enabled" — every real vertical's gating is already
   *  reflected server-side via MFE-registry presence (see `NavLiveness`
   *  below) — but `app.flag`/`app.anyFlag` and this field exist so the
   *  helper is independently testable and so a future direct flag consumer
   *  has a typed, mirrored seam to plug into. */
  readonly flags: ReadonlySet<PlatformFeatureFlag>;
  /** Studio nodeTypes an org admin has disabled — mirrors
   *  `useStudioTools().disabledNodeTypes`. REQUIRED (not optional): an
   *  omitted gate must never silently show a disabled tool. Only Studio's
   *  children carry a `nodeType`, so this has no effect elsewhere. */
  readonly disabledStudioTools: ReadonlySet<string>;
  /** Mirrors `useStudioTools().offlineMode`. REQUIRED for the same reason as
   *  `disabledStudioTools` — when `true`, children whose `nodeType` is in
   *  `OFFLINE_RESTRICTED_STUDIO_NODE_TYPES` are hidden regardless of the
   *  disabled set. */
  readonly studioOfflineMode: boolean;
}

/** Tri-state resolution of "is this destination reachable right now". */
export type NavLivenessState = "live" | "dead" | "pending";

/** Input to `resolveLiveness` — everything needed to decide row REACHABILITY. */
export interface NavLiveness {
  readonly mfes: ReadonlySet<MfeName>;
  readonly status: "loading" | "ready" | "error";
  /** Tri-state INCLUDING `undefined` (`Topbar.tsx:303-311`) — a third
   *  gating axis independent of role and flag. */
  readonly hasWorkspace: boolean | undefined;
}

// ── Taxonomy ────────────────────────────────────────────────────────────

/**
 * Six groups. Originally eight (`plan` and `help-support` also existed,
 * reusing all five legacy platform section keys unchanged), but a product
 * ruling made after the initial taxonomy plan (ticket #2593) dropped the six
 * always-dead `href: null` placeholders those two groups existed to hold —
 * see the registry comment below. With no members left, `plan` and
 * `help-support` are removed too rather than surviving as permanently-empty
 * groups `getVisibleGroups` would just filter out anyway. Legacy's `sense`
 * merges into `engage` (Monitor is the only sense-class destination);
 * `library` merges into `organize` (Files is the platform's library;
 * legacy's split existed for Knowledge and Tables, both removed). `start`
 * and `govern` are new.
 */
export const NAV_GROUP_SLUGS = [
  "start",
  "organize",
  "create-test",
  "engage",
  "govern",
  "admin",
] as const;

export type NavGroupSlug = (typeof NAV_GROUP_SLUGS)[number];

/** Static group metadata — heading label only. Membership is derived from
 *  `NavApp.group`, not stored here, so a group can never drift from its
 *  apps' own declarations. */
const NAV_GROUP_LABELS: Readonly<Record<NavGroupSlug, NavLabelKey>> = {
  start: "nav_section_start",
  organize: "nav_section_organize",
  "create-test": "nav_section_create_test",
  engage: "nav_section_engage",
  govern: "nav_section_govern",
  admin: "nav_admin_group",
};

/** A resolved, non-empty group ready to render — see `getVisibleGroups`. */
export interface NavGroup {
  readonly slug: NavGroupSlug;
  readonly labelKey: NavLabelKey;
  readonly apps: readonly NavApp[];
}

// ── App / child shape ───────────────────────────────────────────────────

/**
 * A sub-route within an app, surfaced in the launcher's preview column.
 * `href` is a real path, optionally carrying a query string (e.g.
 * `/studio?task=audience-profile`) — it is never `null` (a childless
 * destination is simply an app with no `children`, not a child with no
 * destination). See `getAppForPath`'s doc for how the query portion is
 * matched.
 */
export interface NavChild {
  /** Globally unique — dot-prefixed with the parent app's id
   *  (`"${appId}.${slug}"`) so the flat id space app ids ∪ child ids never
   *  collides, even across apps that reuse a route segment (e.g. dialogue's
   *  and monitor's both have a "dashboard" child). */
  readonly id: string;
  readonly labelKey: NavLabelKey;
  readonly href: string;
  /** The Studio org-gate key (`STUDIO_TASKS_CONFIG[].nodeType`, mirrored by
   *  hand — platform-chrome cannot import studio-mfe). When present,
   *  `getVisibleChildren` hides this child if `ctx.disabledStudioTools` has
   *  it, or if `ctx.studioOfflineMode` is true and it is in
   *  `OFFLINE_RESTRICTED_STUDIO_NODE_TYPES`. `undefined` for every
   *  non-Studio child — those are never gated this way. */
  readonly nodeType?: string;
}

export interface NavApp {
  readonly id: NavAppId;
  readonly labelKey: NavLabelKey;
  readonly icon: LucideIcon;
  readonly group: NavGroupSlug;
  /** `null` is how the six always-dead placeholders live in the registry
   *  instead of in hand-written `dead()` calls — it makes "no destination"
   *  impossible to confuse with "MFE offline". */
  readonly href: string | null;
  readonly plane: NavPlane;
  readonly minOrgRole: NavOrgRole;
  /** The backing MFE, when this app is one of the eleven workspace
   *  verticals (or "admin"). `undefined` for Home and Settings — those two
   *  must never dead-flicker while the registry loads (see the module doc's
   *  liveness resolution order) — and for the six placeholders. */
  readonly mfe?: MfeName;
  /** The platform feature-flag key gating this app's backing MFE. Usually
   *  equal to `mfe`, EXCEPT workflow (`mfe: "workflow"`, `flag: "workflows"`)
   *  — see `MFE_NAMES`'s doc comment for why the two fields are never
   *  derived from one another. */
  readonly flag?: PlatformFeatureFlag;
  /** Visible when ANY of these flags is enabled, instead of a single
   *  `flag`. No app in this registry currently needs it (every vertical
   *  maps to exactly one flag) — it exists so `isAppVisible` is exercised
   *  and correct for the day one does. */
  readonly anyFlag?: readonly PlatformFeatureFlag[];
  readonly children?: readonly NavChild[];
}

/**
 * Every app id in this registry, in declaration order. Kept as an explicit
 * union (not derived via `(typeof NAV_APPS)[number]["id"]`) so
 * `NAV_APP_BY_ID` below can be written as a literal object and get a
 * compile error the moment an id is added here without a matching entry —
 * that's what makes `getAppById` TOTAL.
 */
export type NavAppId =
  | "home"
  | "chat"
  | "rooms"
  | "files"
  | "spaces"
  | "studio"
  | "workflows"
  | "range"
  | "queue"
  | "dialogue"
  | "ask"
  | "monitor"
  | "settings"
  | "admin";

// ── Registry ────────────────────────────────────────────────────────────
//
// 14 apps. An earlier wave declared 20 — the 19 from the original ticket
// set (including six always-dead placeholders: Agents, Plan, Objectives,
// Amplify, Learn, User Guide, all `href: null`) plus Spaces — so Task 2's
// "no visual change" refactor had the placeholders' existing assertions to
// refactor onto. A product ruling made after that (ticket #2593, "THE
// TRUNK" of the launcher-grid rework) dropped all six: a header-less
// "coming soon" row reads as a roadmap in a 280px column, but reads as
// visibly broken alignment in a 3-column grid with a preview pane. Their
// two now-empty groups (`plan`, `help-support`) were removed with them —
// see `NAV_GROUP_SLUGS`'s doc comment.
//
// `govern` and `admin` are two distinct groups, and BOTH are bespoke footer
// chips (ticket #2597), not launcher-grid columns. `govern` holds Settings
// (the org-admin surface at /admin/organization, reachable by an org-root
// OWNER/ADMIN while their `plane` stays "workspace"), gated on
// `canReachAdmin` (admin-mfe registry presence) rather than
// `NavContext.orgRole` — see `PrimaryNavMenu.tsx`. `admin` holds the single
// Admin entry (`plane: "admin"`, reachable only when the caller's own
// registry IS the admin-plane one), gated the ordinary way via
// `isAppVisible` (its `minOrgRole` is "none", so only `plane` matters).
// Neither group ever appears in `LAUNCHER_COLUMN_GROUP_SLUGS`.
const NAV_APP_BY_ID: Readonly<Record<NavAppId, NavApp>> = {
  home: {
    id: "home",
    labelKey: "nav_home",
    icon: Home,
    group: "start",
    href: "/",
    plane: "workspace",
    minOrgRole: "none",
    // Deliberately no `mfe` — Home must never dead-flicker while the
    // registry loads (liveness resolution order, step 2).
  },
  chat: {
    id: "chat",
    labelKey: "nav_chat",
    icon: MessagesSquare,
    group: "start",
    href: "/clio",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "clio",
    flag: "clio",
  },
  rooms: {
    id: "rooms",
    labelKey: "nav_rooms",
    icon: MessageCircleMore,
    group: "organize",
    href: "/rooms",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "rooms",
    flag: "rooms",
    children: [
      { id: "rooms.all-rooms", labelKey: "rooms_nav_all_rooms", href: "/rooms" },
      // /rooms/browse has no dedicated route today (RoomsApp.tsx's
      // catch-all swallows it, RoomsApp.tsx:37) — declared anyway to match
      // rooms-mfe's own sidebar (RoomsLayout.tsx:55). Flagged, not fixed.
      { id: "rooms.browse", labelKey: "rooms_nav_browse", href: "/rooms/browse" },
    ],
  },
  files: {
    id: "files",
    labelKey: "nav_files_item",
    icon: Files,
    group: "organize",
    href: "/files",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "files",
    flag: "files",
    // Deliberately childless: tabs are in-page state, not URLs.
  },
  spaces: {
    id: "spaces",
    labelKey: "nav_spaces",
    icon: Layers,
    group: "organize",
    href: "/spaces",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "spaces",
    flag: "spaces",
  },
  studio: {
    id: "studio",
    labelKey: "nav_studio",
    icon: PencilSparkles,
    group: "create-test",
    href: "/studio",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "studio",
    flag: "studio",
    // Destinations are `?task=` query params (`/studio?task=<id>`), not
    // distinct paths — `getAppForPath` takes an optional `search` argument
    // so these still resolve to the specific child, and `matchLength`
    // ignores the query when matching the path portion. Order mirrors
    // `STUDIO_TASKS_CONFIG` in studio-mfe/src/config/studioTasks.ts exactly
    // (hand-mirrored — platform-chrome cannot import studio-mfe).
    children: [
      { id: "studio.audience-profile", labelKey: "studio_task_audience_profile_name", href: "/studio?task=audience-profile", nodeType: "audience_profile" },
      { id: "studio.brand-profile", labelKey: "studio_task_brand_profile_name", href: "/studio?task=brand-profile", nodeType: "brand_profile" },
      { id: "studio.voice-profile", labelKey: "studio_task_voice_profile_name", href: "/studio?task=voice-profile", nodeType: "voice_profile" },
      { id: "studio.research-assistant", labelKey: "studio_task_research_assistant_name", href: "/studio?task=research-assistant", nodeType: "research_assistant" },
      { id: "studio.content-planner", labelKey: "studio_task_content_planner_name", href: "/studio?task=content-planner", nodeType: "content_planner" },
      { id: "studio.content-creator", labelKey: "studio_task_content_creator_name", href: "/studio?task=content-creator", nodeType: "content_studio" },
      { id: "studio.content-testing", labelKey: "studio_task_content_testing_name", href: "/studio?task=content-testing", nodeType: "test_content" },
      { id: "studio.translation", labelKey: "studio_task_translation_name", href: "/studio?task=translation", nodeType: "translation" },
      { id: "studio.qr-code", labelKey: "studio_task_qr_code_name", href: "/studio?task=qr-code", nodeType: "qr_code" },
      { id: "studio.image-workspace", labelKey: "studio_task_image_workspace_name", href: "/studio?task=image-workspace", nodeType: "image_workspace" },
      { id: "studio.image-suggestions", labelKey: "studio_task_image_suggestions_name", href: "/studio?task=image-suggestions", nodeType: "image_suggestions" },
      { id: "studio.storyboard-task", labelKey: "studio_task_storyboard_task_name", href: "/studio?task=storyboard-task", nodeType: "storyboard_creator" },
      { id: "studio.design-canvas", labelKey: "studio_task_design_canvas_name", href: "/studio?task=design-canvas", nodeType: "design_canvas" },
      { id: "studio.text-to-speech", labelKey: "studio_task_text_to_speech_name", href: "/studio?task=text-to-speech", nodeType: "text_to_speech" },
      { id: "studio.audio-to-text", labelKey: "studio_task_audio_to_text_name", href: "/studio?task=audio-to-text", nodeType: "audio_to_text" },
      { id: "studio.video-to-text", labelKey: "studio_task_video_to_text_name", href: "/studio?task=video-to-text", nodeType: "video_to_text" },
      { id: "studio.segmentation", labelKey: "studio_task_segmentation_name", href: "/studio?task=segmentation", nodeType: "segmentation" },
      { id: "studio.propaganda-analysis", labelKey: "studio_task_propaganda_analysis_name", href: "/studio?task=propaganda-analysis", nodeType: "propaganda_analysis" },
      { id: "studio.character-studio", labelKey: "studio_task_character_studio_name", href: "/studio?task=character-studio", nodeType: "character_generator" },
    ],
  },
  workflows: {
    id: "workflows",
    labelKey: "nav_workflows",
    icon: GitFork,
    group: "create-test",
    href: "/workflows",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "workflow",
    flag: "workflows",
    children: [
      { id: "workflows.canvas", labelKey: "workflow_nav_canvas", href: "/workflows/canvas" },
      { id: "workflows.templates", labelKey: "workflow_nav_templates", href: "/workflows/templates" },
      { id: "workflows.projects", labelKey: "workflow_nav_projects", href: "/workflows/projects" },
    ],
  },
  range: {
    id: "range",
    labelKey: "nav_range",
    icon: Target,
    group: "create-test",
    href: "/range",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "range",
    flag: "range",
    // Deliberately childless: everything is per-exercise
    // `/range/exercises/:id/...`, needing session state a path matcher
    // cannot supply.
  },
  queue: {
    id: "queue",
    labelKey: "nav_queue",
    icon: CalendarClock,
    group: "engage",
    href: "/queue",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "queue",
    flag: "queue",
    children: [
      // QueueApp mounts QueueLandingRoute (Posts) at "/" — this child's
      // href deliberately TIES with the parent app's own href. See
      // `getAppForPath`'s doc: a tie keeps the first-matched entry, which
      // is the app itself, not this child.
      { id: "queue.posts", labelKey: "queue_nav_posts", href: "/queue" },
      { id: "queue.calendar", labelKey: "queue_nav_calendar", href: "/queue/calendar" },
      { id: "queue.table", labelKey: "queue_nav_table", href: "/queue/table" },
      { id: "queue.analytics", labelKey: "queue_nav_analytics", href: "/queue/analytics" },
      { id: "queue.accounts", labelKey: "queue_nav_accounts", href: "/queue/accounts" },
      { id: "queue.triggers", labelKey: "queue_nav_triggers", href: "/queue/triggers" },
    ],
  },
  dialogue: {
    id: "dialogue",
    labelKey: "nav_dialogue_item",
    icon: MessageSquareQuote,
    group: "engage",
    href: "/dialogue",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "dialogue",
    flag: "dialogue",
    children: [
      { id: "dialogue.dashboard", labelKey: "dialogue_subnav_dashboard", href: "/dialogue/dashboard" },
      { id: "dialogue.conversations", labelKey: "dialogue_subnav_conversations", href: "/dialogue/conversations" },
      { id: "dialogue.channels", labelKey: "dialogue_subnav_channels", href: "/dialogue/channels" },
      { id: "dialogue.contacts", labelKey: "dialogue_subnav_contacts", href: "/dialogue/contacts" },
      { id: "dialogue.templates", labelKey: "dialogue_subnav_templates", href: "/dialogue/templates" },
      { id: "dialogue.broadcasts", labelKey: "dialogue_subnav_broadcasts", href: "/dialogue/broadcasts" },
      { id: "dialogue.recipes", labelKey: "dialogue_subnav_recipes", href: "/dialogue/recipes" },
      { id: "dialogue.tags", labelKey: "dialogue_subnav_tags", href: "/dialogue/tags" },
    ],
  },
  ask: {
    id: "ask",
    labelKey: "nav_ask",
    icon: LayoutList,
    group: "engage",
    href: "/ask",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "ask",
    flag: "ask",
    children: [
      { id: "ask.surveys", labelKey: "ask_nav_surveys", href: "/ask/surveys" },
      { id: "ask.analytics", labelKey: "ask_nav_analytics", href: "/ask/analytics" },
      { id: "ask.settings", labelKey: "ask_nav_settings", href: "/ask/settings" },
    ],
  },
  monitor: {
    id: "monitor",
    labelKey: "nav_monitor",
    icon: Activity,
    group: "engage",
    href: "/monitor",
    plane: "workspace",
    minOrgRole: "none",
    mfe: "monitor",
    flag: "monitor",
    children: [
      { id: "monitor.dashboard", labelKey: "nav_monitor_dashboard", href: "/monitor/dashboard" },
      { id: "monitor.search", labelKey: "monitor_sidebar_search", href: "/monitor/search" },
      { id: "monitor.trends", labelKey: "monitor_sidebar_trends", href: "/monitor/trends" },
      { id: "monitor.web-scraper", labelKey: "monitor_sidebar_web_scraper", href: "/monitor/web-scraper" },
      { id: "monitor.social-listening", labelKey: "monitor_sidebar_social_listening", href: "/monitor/social-listening" },
      { id: "monitor.posts", labelKey: "monitor_sidebar_posts", href: "/monitor/posts" },
      { id: "monitor.digital-twins", labelKey: "monitor_sidebar_digital_twins", href: "/monitor/digital-twins" },
    ],
  },
