export const NAV_APPS: readonly NavApp[] = Object.values(NAV_APP_BY_ID);

/**
 * Mirrors studio-mfe's `OFFLINE_RESTRICTED_NODE_TYPES`
 * (`frontends/studio-mfe/src/config/studioTasks.ts`) by hand — platform-chrome
 * cannot import studio-mfe (studio-mfe depends on platform-chrome, never the
 * reverse). A sibling mirror test asserts set equality against the source.
 */
export const OFFLINE_RESTRICTED_STUDIO_NODE_TYPES = ["research_assistant"] as const;

// ── Helpers ─────────────────────────────────────────────────────────────

/**
 * `getAppById` is deliberately UNFILTERED (ignores visibility/liveness) and
 * TOTAL — `NavAppId` is a closed union over a module-scope `Record`, so no
 * call site ever needs to write a meaningless `?? fallback`.
 */
export function getAppById(id: NavAppId): NavApp {
  return NAV_APP_BY_ID[id];
}

/**
 * Visibility: does this row exist in the menu at all. Independent of
 * `resolveLiveness` — see the module doc's "Visibility vs. liveness"
 * section.
 */
export function isAppVisible(app: NavApp, ctx: NavContext): boolean {
  if (app.plane !== ctx.plane) return false;
  if (ORG_ROLE_RANK[ctx.orgRole] < ORG_ROLE_RANK[app.minOrgRole]) return false;
  if (app.anyFlag && app.anyFlag.length > 0) {
    if (!app.anyFlag.some((flag) => ctx.flags.has(flag))) return false;
  } else if (app.flag) {
    if (!ctx.flags.has(app.flag)) return false;
  }
  return true;
}

/**
 * Liveness: is this row's destination reachable right now. See the module
 * doc's exact resolution order.
 */
export function resolveLiveness(
  app: NavApp,
  live: NavLiveness,
): NavLivenessState {
  if (app.href === null) return "dead";
  if (app.mfe === undefined) return "live";
  if (live.status === "loading") return "pending";
  if (live.hasWorkspace === false) return "dead";
  return live.mfes.has(app.mfe) ? "live" : "dead";
}

/** All groups with at least one visible app, in `NAV_GROUP_SLUGS` order,
 *  each app-list itself filtered to only visible apps. Empty groups drop. */
export function getVisibleGroups(ctx: NavContext): readonly NavGroup[] {
  const groups: NavGroup[] = [];
  for (const slug of NAV_GROUP_SLUGS) {
    const apps = NAV_APPS.filter(
      (app) => app.group === slug && isAppVisible(app, ctx),
    );
    if (apps.length === 0) continue;
    groups.push({ slug, labelKey: NAV_GROUP_LABELS[slug], apps });
  }
  return groups;
}

/** Every visible app, in `NAV_APPS` declaration order (flattened across
 *  groups — use `getVisibleGroups` when group boundaries matter). */
export function getVisibleApps(ctx: NavContext): readonly NavApp[] {
  return NAV_APPS.filter((app) => isAppVisible(app, ctx));
}

/** An app's children, or `[]` for a childless app or one hidden by `ctx`.
 *  A child carrying `nodeType` is additionally hidden when that nodeType is
 *  in `ctx.disabledStudioTools`, or when `ctx.studioOfflineMode` is true and
 *  the nodeType is offline-restricted (`OFFLINE_RESTRICTED_STUDIO_NODE_TYPES`).
 *  A child with no `nodeType` is never gated by either check. */
export function getVisibleChildren(
  app: NavApp,
  ctx: NavContext,
): readonly NavChild[] {
  if (!isAppVisible(app, ctx)) return [];
  return (app.children ?? []).filter((child) => {
    if (child.nodeType === undefined) return true;
    if (ctx.disabledStudioTools.has(child.nodeType)) return false;
    if (
      ctx.studioOfflineMode &&
      (OFFLINE_RESTRICTED_STUDIO_NODE_TYPES as readonly string[]).includes(
        child.nodeType,
      )
    ) {
      return false;
    }
    return true;
  });
}

/** A single flattened destination: either an app or one of its children. */
export interface NavDestination {
  readonly app: NavApp;
  readonly child: NavChild | null;
}

/** Every visible app, each paired once with `child: null` and once more per
 *  visible child — the flat list Tasks 2/9 render/search over. */
export function getVisibleDestinations(
  ctx: NavContext,
): readonly NavDestination[] {
  const out: NavDestination[] = [];
  for (const app of getVisibleApps(ctx)) {
    out.push({ app, child: null });
    for (const child of getVisibleChildren(app, ctx)) {
      out.push({ app, child });
    }
  }
  return out;
}

/**
 * Longest-match, segment-safe path resolution. Keeps legacy's rules —
 * longest match wins; a tie keeps the FIRST-matched entry (`>`, not `>=`);
 * "/" matches EXACTLY only, never by prefix — and adds three changes forced
 * by real platform routes: it searches children too and reports WHICH one
 * matched; it skips `href === null` (a placeholder can never be "current");
 * and children are checked after their own app in iteration order, so a
 * tie between a parent and its own child (`/queue` the app vs. `/queue` the
 * Posts child) keeps the PARENT — see the `queue` app's `children` comment.
 *
 * The optional `search` argument (the current location's query string, e.g.
 * `"?task=voice-profile"`) lets a query-addressed child (Studio's
 * `/studio?task=<id>`) win over its own parent app. A child href is split
 * into its path and query portions; the path portion is matched exactly like
 * any other href (so `matchLength` never needs to know about queries at
 * all), and among children whose path matches, one whose query portion
 * equals `search` wins outright — irrespective of path length — over the
 * parent (which carries no query) or a query-less child. An unrecognized or
 * absent `?task=` value falls back to ordinary longest-match, i.e. the app
 * itself for `/studio`.
 */
export function getAppForPath(
  pathname: string,
  search = "",
): NavDestination | null {
  let best: NavDestination | null = null;
  let bestLength = -1;

  for (const app of NAV_APPS) {
    if (app.href !== null) {
      const length = matchLength(app.href, pathname);
      if (length !== null && length > bestLength) {
        best = { app, child: null };
        bestLength = length;
      }
    }
    for (const child of app.children ?? []) {
      const [childPath, childQuery] = splitHref(child.href);
      const length = matchLength(childPath, pathname);
      if (length === null) continue;
      if (childQuery !== "" && childQuery === search) {
        // Exact query match wins outright — it identifies a specific child
        // more precisely than any path-length comparison could.
        return { app, child };
      }
      if (length > bestLength) {
        best = { app, child };
        bestLength = length;
      }
    }
  }

  return best;
}

/** Splits an `href` into its path and query portions, e.g.
 *  `"/studio?task=x"` → `["/studio", "?task=x"]`. A plain path href (no `?`)
 *  returns an empty-string query. */
function splitHref(href: string): readonly [path: string, query: string] {
  const i = href.indexOf("?");
  return i === -1 ? [href, ""] : [href.slice(0, i), href.slice(i)];
}

/** `href.length` if `pathname` matches `href` (exactly, or as a `/`-bounded
 *  prefix), else `null`. "/" is special-cased to match ONLY "/" exactly —
 *  every other route matches its own subtree. */
function matchLength(href: string, pathname: string): number | null {
  if (href === "/") return pathname === "/" ? href.length : null;
  if (pathname === href || pathname.startsWith(`${href}/`)) return href.length;
  return null;
}


