/**
 * navigation.ts — the platform-chrome navigation registry.
 *
 * PURE DATA. No Paraglide import — `labelKey` is plain string data (a key
 * into `navigationLabels.ts`'s `NAV_LABELS`), so this module can be imported
 * by a Node script or a test with zero Paraglide/React runtime cost. The
 * only non-data import is the shared lucide icon barrel, for `NavApp.icon`
 * (a component reference, asserted unique by identity — see
 * `navigation.test.ts` — never by its stamped CSS class).
 *
 * ── Two role axes, never one ──────────────────────────────────────────────
 *
 * Legacy's single `NavRole` does not transfer to this platform:
 *
 *   - `NavPlane` mirrors shell-bff's OWN partitioning of the MFE registry
 *     (`services/shell-bff/internal/handlers/mfes.go:159-165`, `:190-291`),
 *     lifted to the client. It is NOT a role: a realm admin/org-admin's
 *     registry contains ONLY admin-mfe (confined, early return), while an
 *     org-root OWNER/ADMIN with no realm role gets admin-mfe PREPENDED to
 *     the eleven workspace MFEs — their plane is still "workspace". Only a
 *     realm admin/org-admin's plane is "admin".
 *   - `NavOrgRole` carries `"none"` as a reachable, named first-class state
 *     (a platform admin has no org-membership row) rather than a falsy `""`
 *     — `if (!orgRole)` is exactly how a fail-open bug gets written. Ranked
 *     via `ORG_ROLE_RANK` so `minOrgRole` gating is a comparison, not a set
 *     test.
 *   - `capabilities` (on the wire at `session.go:101`) is deliberately NOT
 *     carried: it's already discarded by the frontend session types, and
 *     realm role "admin" force-grants all seven while `org_role` stays `""`
 *     (`session.go:196-201`) — a strictly weaker discriminator than
 *     plane + orgRole.
 *
 * ── Visibility vs. liveness — two functions over two input objects ───────
 *
 * `isAppVisible(app, ctx: NavContext)` answers "does this row exist in the
 * menu at all" (role/plane/flag gating — an invisible row renders nothing,
 * not a dead placeholder). `resolveLiveness(app, live: NavLiveness)`
 * answers "is this row's destination reachable right now", independent of
 * visibility, in three states — `"pending"` is what fixes the DEAD-flash
 * without adding a fourth render path. Resolution order (first match wins):
 *
 *   1. `href === null`        → dead     (the six placeholders)
 *   2. `mfe === undefined`    → live     (Home/Settings must never flicker)
 *   3. `status === "loading"` → pending
 *   4. `hasWorkspace === false` → dead
 *   5. `mfes.has(mfe)`        → live, else dead
 */

import {
  Activity,
  CalendarClock,
  Files,
  GitFork,
  Home,
  Layers,
  MessageCircleMore,
  MessageSquareQuote,
  MessagesSquare,
  PencilSparkles,
  Settings,
  Shield,
  Target,
  LayoutList,
  type LucideIcon,
} from "@omnicore-platform/ui/icons";
import type { NavLabelKey } from "./navigationLabels";

// ── Role axes ────────────────────────────────────────────────────────────

/**
 * shell-bff's own MFE-registry partitioning, lifted to the client. NOT a
 * role — see the module doc above.
 */
export type NavPlane = "workspace" | "admin";

/**
 * The caller's ORG-ROOT membership role. `"none"` is a reachable first-class
 * state, not a falsy sentinel — see the module doc above.
 */
export type NavOrgRole = "none" | "VIEWER" | "MEMBER" | "ADMIN" | "OWNER";

/**
 * Rank table for `NavOrgRole`, so `minOrgRole` gating is a numeric
 * comparison (`ORG_ROLE_RANK[ctx.orgRole] >= ORG_ROLE_RANK[app.minOrgRole]`)
 * rather than a set-membership test that has to be kept in sync by hand.
 */
export const ORG_ROLE_RANK: Readonly<Record<NavOrgRole, number>> = {
  none: 0,
  VIEWER: 1,
  MEMBER: 2,
  ADMIN: 3,
  OWNER: 4,
};

// ── Feature flags and MFE names — closed, mirrored unions ─────────────────

/**
 * Platform-global vertical flag keys. Mirrors
 * `services/org-svc/internal/domain/feature_flag.go`'s `KnownVerticalKeys`
 * exactly (order included) — `navigation.mirror.test.ts` parses that file
 * and asserts set equality. This is the first place in the repo where a
 * known-key typo is a BUILD failure: today `RequireVerticalEnabled("filez")`
 * is caught by nothing (the cache fails open, so the gate becomes a
 * permanent silent no-op).
 */
export const PLATFORM_FEATURE_FLAGS = [
  "dialogue",
  "range",
  "spaces",
  "studio",
  "ask",
  "workflows",
  "clio",
  "files",
  "monitor",
  "queue",
  "rooms",
] as const;

export type PlatformFeatureFlag = (typeof PLATFORM_FEATURE_FLAGS)[number];

/**
 * Registered Module Federation remote names. Mirrors
 * `services/shell-bff/internal/handlers/mfes.go`'s registry entries — the
 * eleven workspace MFEs plus "admin" — exactly.
 * `navigation.mirror.test.ts` parses that file and asserts set equality.
 *
 * NOTE the three spellings: MFE name "workflow" (singular), flag key
 * "workflows" (plural), route "/workflows". shell-bff carries a separate
 * `flagKey` column solely for this (`mfes.go:259-264`); `NavApp` mirrors
 * that split with separate `mfe` and `flag` fields rather than deriving one
 * from the other — deriving one from the other IS the trap, and it is the
 * live `/workflow` 404 in the command palette today.
 */
export const MFE_NAMES = [
  "admin",
  "files",
  "dialogue",
  "range",
  "clio",
  "workflow",
  "studio",
  "spaces",
  "ask",
  "queue",
  "monitor",
  "rooms",
] as const;

export type MfeName = (typeof MFE_NAMES)[number];

// ── Visibility ──────────────────────────────────────────────────────────

/** Input to `isAppVisible` — everything needed to decide row EXISTENCE. */
export interface NavContext {
  readonly plane: NavPlane;
  readonly orgRole: NavOrgRole;
  /** Currently-enabled platform feature flags. In production this is
   *  effectively "all enabled" — every real vertical's gating is already
   *  reflected server-side via MFE-registry presence (see `NavLiveness`
   *  below) — but `app.flag`/`app.anyFlag` and this field exist so the
   *  helper is independently testable and so a future direct flag consumer
   *  has a typed, mirrored seam to plug into. */
  readonly flags: ReadonlySet<PlatformFeatureFlag>;
  /** Studio nodeTypes an org admin has disabled — mirrors
   *  `useStudioTools().disabledNodeTypes`. REQUIRED (not optional): an
   *  omitted gate must never silently show a disabled tool. Only Studio's
   *  children carry a `nodeType`, so this has no effect elsewhere. */
  readonly disabledStudioTools: ReadonlySet<string>;
  /** Mirrors `useStudioTools().offlineMode`. REQUIRED for the same reason as
   *  `disabledStudioTools` — when `true`, children whose `nodeType` is in
   *  `OFFLINE_RESTRICTED_STUDIO_NODE_TYPES` are hidden regardless of the
   *  disabled set. */
  readonly studioOfflineMode: boolean;
}

/** Tri-state resolution of "is this destination reachable right now". */
export type NavLivenessState = "live" | "dead" | "pending";

/** Input to `resolveLiveness` — everything needed to decide row REACHABILITY. */
export interface NavLiveness {
  readonly mfes: ReadonlySet<MfeName>;
  readonly status: "loading" | "ready" | "error";
  /** Tri-state INCLUDING `undefined` (`Topbar.tsx:303-311`) — a third
   *  gating axis independent of role and flag. */
  readonly hasWorkspace: boolean | undefined;
}

// ── Taxonomy ────────────────────────────────────────────────────────────

/**
 * Six groups. Originally eight (`plan` and `help-support` also existed,
 * reusing all five legacy platform section keys unchanged), but a product
 * ruling made after the initial taxonomy plan (ticket #2593) dropped the six
 * always-dead `href: null` placeholders those two groups existed to hold —
 * see the registry comment below. With no members left, `plan` and
 * `help-support` are removed too rather than surviving as permanently-empty
 * groups `getVisibleGroups` would just filter out anyway. Legacy's `sense`
 * merges into `engage` (Monitor is the only sense-class destination);
 * `library` merges into `organize` (Files is the platform's library;
 * legacy's split existed for Knowledge and Tables, both removed). `start`
 * and `govern` are new.
 */
export const NAV_GROUP_SLUGS = [
  "start",
  "organize",
  "create-test",
  "engage",
  "govern",
  "admin",
] as const;

export type NavGroupSlug = (typeof NAV_GROUP_SLUGS)[number];

/** Static group metadata — heading label only. Membership is derived from
