export function isAppVisible(app: NavApp, ctx: NavContext): boolean {
  if (app.plane !== ctx.plane) return false;
  if (ORG_ROLE_RANK[ctx.orgRole] < ORG_ROLE_RANK[app.minOrgRole]) return false;
  if (app.anyFlag && app.anyFlag.length > 0) {
    if (!app.anyFlag.some((flag) => ctx.flags.has(flag))) return false;
  } else if (app.flag) {
    if (!ctx.flags.has(app.flag)) return false;
