export function getVisibleGroups(ctx: NavContext): readonly NavGroup[] {
  const groups: NavGroup[] = [];
  for (const slug of NAV_GROUP_SLUGS) {
    const apps = NAV_APPS.filter(
      (app) => app.group === slug && isAppVisible(app, ctx),
    );
    if (apps.length === 0) continue;
    groups.push({ slug, labelKey: NAV_GROUP_LABELS[slug], apps });
  }
  return groups;
