 *  the nodeType is offline-restricted (`OFFLINE_RESTRICTED_STUDIO_NODE_TYPES`).
 *  A child with no `nodeType` is never gated by either check. */
export function getVisibleChildren(
  app: NavApp,
  ctx: NavContext,
