/**
 * Longest-match, segment-safe path resolution. Keeps legacy's rules —
 * longest match wins; a tie keeps the FIRST-matched entry (`>`, not `>=`);
 * "/" matches EXACTLY only, never by prefix — and adds three changes forced
 * by real platform routes: it searches children too and reports WHICH one
 * matched; it skips `href === null` (a placeholder can never be "current");
 * and children are checked after their own app in iteration order, so a
 * tie between a parent and its own child (`/queue` the app vs. `/queue` the
 * Posts child) keeps the PARENT — see the `queue` app's `children` comment.
 *
 * The optional `search` argument (the current location's query string, e.g.
 * `"?task=voice-profile"`) lets a query-addressed child (Studio's
 * `/studio?task=<id>`) win over its own parent app. A child href is split
 * into its path and query portions; the path portion is matched exactly like
 * any other href (so `matchLength` never needs to know about queries at
 * all), and among children whose path matches, one whose query portion
 * equals `search` wins outright — irrespective of path length — over the
 * parent (which carries no query) or a query-less child. An unrecognized or
 * absent `?task=` value falls back to ordinary longest-match, i.e. the app
 * itself for `/studio`.
 */
export function getAppForPath(
  pathname: string,
  search = "",
): NavDestination | null {
  let best: NavDestination | null = null;
  let bestLength = -1;

  for (const app of NAV_APPS) {
    if (app.href !== null) {
      const length = matchLength(app.href, pathname);
      if (length !== null && length > bestLength) {
        best = { app, child: null };
        bestLength = length;
      }
    }
    for (const child of app.children ?? []) {
      const [childPath, childQuery] = splitHref(child.href);
      const length = matchLength(childPath, pathname);
      if (length === null) continue;
      if (childQuery !== "" && childQuery === search) {
        // Exact query match wins outright — it identifies a specific child
        // more precisely than any path-length comparison could.
        return { app, child };
      }
      if (length > bestLength) {
        best = { app, child };
        bestLength = length;
      }
    }
  }

  return best;
}

/** Splits an `href` into its path and query portions, e.g.
 *  `"/studio?task=x"` → `["/studio", "?task=x"]`. A plain path href (no `?`)
 *  returns an empty-string query. */
function splitHref(href: string): readonly [path: string, query: string] {
  const i = href.indexOf("?");
  return i === -1 ? [href, ""] : [href.slice(0, i), href.slice(i)];
}

/** `href.length` if `pathname` matches `href` (exactly, or as a `/`-bounded
 *  prefix), else `null`. "/" is special-cased to match ONLY "/" exactly —
 *  every other route matches its own subtree. */
function matchLength(href: string, pathname: string): number | null {
  if (href === "/") return pathname === "/" ? href.length : null;
  if (pathname === href || pathname.startsWith(`${href}/`)) return href.length;
  return null;
}


